var PRINTED_LINES = [
  '解：设未知数为 x',
  '由题意列方程',
  '移项得'
];

const visual = {
  prepare: function (input) {
    return PRINTED_LINES.map(function (line) {
      return { kind: 'text', payload: line };
    });
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var fontSize = Math.max(16, Math.min(26, Math.floor(W / 22)));
    var lineHeight = fontSize * 1.8;
    var startX = Math.max(32, Math.min(72, W * 0.12));
    var startY = Math.max(48, Math.min(110, H * 0.22));
    var children = [];
    for (var i = 0; i < PRINTED_LINES.length; i++) {
      children.push({
        type: 'label',
        x: startX,
        y: startY + i * lineHeight,
        text: PRINTED_LINES[i],
        fontSize: fontSize,
        fontFamily: 'sans-serif',
        fontWeight: 'normal',
        fill: '#1f2937',
        textAnchor: 'start',
        dominantBaseline: 'alphabetic'
      });
    }
    return {
      schemaVersion: 1,
      sceneId: 'clean-printed-solution',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [],
      root: { type: 'group', children: children }
    };
  }
};
